import networkx as nx
import json
import math
import os
import random
import pandas as pd
from itertools import islice
from typing import Dict, List


def exact_steiner_tree(Uw, terms):
    """Dreyfus-Wagner exact Steiner tree on undirected graph Uw (edge
    attr 'cost') over terminal list terms (terms[0] must be src).

    Subset DP: C[v][mask] = min cost of a tree connecting terminals in
    `mask` plus node v. Two-phase recurrence per mask: (1) merge submasks
    (3^k total work), (2) one min-plus edge relaxation pass using the
    *final* C[u][mask] of neighbors (single pass suffices since the edge
    term is min_u C[u][mask] + w(u,v)). Argmin decomposition choices are
    recorded in merge_split / epar and backtracked to recover the optimal
    tree edges. Returns an nx.Graph of the optimal tree, or None if some
    terminal is unreachable. O(3^k * n + 2^k * m).
    """
    nodes = list(Uw.nodes)
    k = len(terms)
    full = (1 << k) - 1
    INF = float("inf")
    C = {v: [INF] * (full + 1) for v in nodes}
    merge_split = {}
    epar = {}
    for i, t in enumerate(terms):
        if t in C:
            C[t][1 << i] = 0.0
    adj = {v: [(u, d["cost"]) for u, d in Uw[v].items()] for v in nodes}
    for mask in range(1, full + 1):
        for v in nodes:
            cv = C[v]
            sub = (mask - 1) & mask
            while sub:
                if cv[sub] + cv[mask ^ sub] < cv[mask]:
                    cv[mask] = cv[sub] + cv[mask ^ sub]
                    merge_split[(v, mask)] = sub
                    epar.pop((v, mask), None)
                sub = (sub - 1) & mask
            for u, w in adj[v]:
                if C[u][mask] + w < cv[mask]:
                    cv[mask] = C[u][mask] + w
                    epar[(v, mask)] = u
                    merge_split.pop((v, mask), None)
    best_v, best_c = None, INF
    for v in nodes:
        if C[v][full] < best_c:
            best_c, best_v = C[v][full], v
    if best_v is None or best_c == INF:
        return None
    tree_edges = set()

    def bt(v, mask):
        if (v, mask) in merge_split:
            s = merge_split[(v, mask)]
            bt(v, s)
            bt(v, mask ^ s)
        elif (v, mask) in epar:
            u = epar[(v, mask)]
            tree_edges.add((u, v))
            bt(u, mask)

    bt(best_v, full)
    T = nx.Graph()
    for u, v in tree_edges:
        T.add_edge(u, v, cost=Uw[u][v]["cost"])
    return T


def search_algorithm(src, dsts, G, num_partitions):
    """Shared-multicast Steiner-tree broadcast.

    Builds an undirected symmetrized graph (edge weight = min of the two
    directed costs), computes a Steiner tree over terminals {src} + dsts,
    orients it from src via BFS, and assigns each dst its unique tree path
    so shared prefixes carry data once instead of per-dst duplicates.
    Falls back to plain Dijkstra for dsts not covered by the tree.
    """
    from networkx.algorithms.approximation.steinertree import steiner_tree

    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    # Symmetrize into an undirected graph with cheap edge weights.
    U = nx.Graph()
    for s, t, data in G.edges(data=True):
        if s == t or data.get("cost") is None:
            continue
        w = data["cost"]
        if U.has_edge(s, t):
            U[s][t]["cost"] = min(U[s][t]["cost"], w)
        else:
            U.add_edge(s, t, cost=w)

    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))

    def edge_data(s, t):
        if G.has_edge(s, t):
            return G[s][t]
        return G[t][s]

    def record(dst, path_nodes):
        for i in range(len(path_nodes) - 1):
            s, t = path_nodes[i], path_nodes[i + 1]
            for j in range(num_partitions):
                bc_topology.append_dst_partition_path(dst, j, [s, t, edge_data(s, t)])

    terminals = {src} | {d for d in dsts if d != src and d in U}

    def dcost(s, t):
        d = edge_data(s, t)
        c = d.get("cost")
        return 0.0 if c is None else c

    def sol_cost(pmap):
        """Exact scored objective: sum of directed costs over the union of
        unique directed edges used by all per-dst paths (shared edges
        charged once, matching the multicast evaluator)."""
        used = set()
        for p in pmap.values():
            for i in range(len(p) - 1):
                used.add((p[i], p[i + 1]))
        return sum(dcost(s, t) for s, t in used)

    def build_solution(weight_mode):
        """Build a Steiner-tree broadcast plan under one symmetrization
        weight mode ('min' or 'sum' of the two directed edge costs), orient
        the tree from src, and polish it with bounded local search
        (re-attach, relay-prune, junction re-root) evaluated on the exact
        directed union-cost objective. Returns (paths_map, cost)."""
        Uw = nx.Graph()
        for s, t, data in G.edges(data=True):
            if s == t or data.get("cost") is None:
                continue
            w = data["cost"]
            if Uw.has_edge(s, t):
                Uw[s][t]["cost"] = (
                    min(Uw[s][t]["cost"], w) if weight_mode == "min"
                    else Uw[s][t]["cost"] + w
                )
            else:
                Uw.add_edge(s, t, cost=w)
        pmap = {}
        if len(terminals) > 1 and nx.is_connected(Uw.subgraph(Uw.nodes)):
            try:
                tl = [src] + [t for t in terminals if t != src]
                if len(tl) <= 12:
                    # Exact optimum seed: removes the 2-approximation gap of
                    # steiner_tree so annealing starts from the best possible
                    # undirected surrogate tree. Falls back to the 2-approx
                    # for larger terminal sets to respect the compute budget.
                    T = exact_steiner_tree(Uw, tl)
                else:
                    T = steiner_tree(Uw, tl, weight="cost")
                if T is not None and src in T:
                    parent = {src: None}
                    order = [src]
                    for node in order:
                        for nbr in T[node]:
                            if nbr not in parent:
                                parent[nbr] = node
                                order.append(nbr)
                    for dst in dsts:
                        if dst != src and dst in parent:
                            pn = []
                            node = dst
                            while node is not None:
                                pn.append(node)
                                node = parent[node]
                            pn.reverse()
                            pmap[dst] = pn
            except Exception:
                pmap = {}

        # Deterministic exhaustive best-response coordinate descent with an
        # EXTENDED neighborhood (replaces the stochastic annealer). Three
        # move classes, all evaluated with the exact directed union-cost
        # objective sol_cost (shared directed edges charged once):
        #   (1) single-dst reroute over up to 12 cached cheapest simple paths;
        #   (2) cross-path joins: prefix of one cached path of dst + suffix
        #       of ANOTHER cached path of the same dst at any common node —
        #       reaches paths not in either cached list;
        #   (3) splices onto other dsts' current paths at shared nodes;
        #   (4) pairwise joint best-response: for each dst pair, evaluate
        #       assigning BOTH dsts simultaneously to shared-prefix
        #       configurations built from the other's cached candidates —
        #       escapes local optima where every single-dst move is
        #       temporarily cost-increasing.
        # Single moves sweep to a fixpoint (cost monotone non-increasing,
        # finite candidate sets => guaranteed convergence); pairwise joint
        # moves then sweep to their own fixpoint. No RNG, deterministic,
        # never worse than the Steiner seed (seed path kept in candidates).
        # Budget: <=6 sweeps x ~(12 + joins + splices) x len(dsts) sol_cost
        # evaluations plus <=3 joint sweeps x pairs — all set-based O(edges),
        # far under the time limit.
        if pmap:
            cand_paths = {}
            for d in pmap:
                try:
                    cand_paths[d] = list(
                        islice(nx.shortest_simple_paths(h, src, d, weight="cost"), 12)
                    )
                except (nx.NetworkXNoPath, nx.NodeNotFound):
                    cand_paths[d] = [pmap[d]]
                if pmap[d] not in cand_paths[d]:
                    cand_paths[d].append(list(pmap[d]))

            def valid(p, d):
                return p and len(p) >= 2 and p[0] == src and p[-1] == d

            # Precompute cross-path joins per dst (candidate class 2).
            join_paths = {}
            for d in pmap:
                joins = []
                pl = cand_paths[d]
                for a_i in range(len(pl)):
                    ia = {v: i for i, v in enumerate(pl[a_i])}
                    for b_i in range(len(pl)):
                        if b_i == a_i:
                            continue
                        pb = pl[b_i]
                        for i, v in enumerate(pb):
                            j = ia.get(v)
                            if j is not None:
                                joins.append(pb[: i + 1] + pl[a_i][j + 1:])
                join_paths[d] = joins

            cur, cur_cost = dict(pmap), sol_cost(pmap)
            dst_list = list(cur)

            # Phase A: single-dst best-response sweeps to fixpoint.
            for _sweep in range(6):
                improved = False
                for dst in dst_list:
                    cp = cur[dst]
                    cp_idx = {v: i for i, v in enumerate(cp)}
                    cands = list(cand_paths[dst]) + list(join_paths[dst])
                    for other in dst_list:
                        if other == dst:
                            continue
                        op = cur[other]
                        op_idx = {v: i for i, v in enumerate(op)}
                        for v, ci in cp_idx.items():
                            oi = op_idx.get(v)
                            if oi is not None:
                                cands.append(op[: oi + 1] + cp[ci + 1:])
                    best_p, best_c = cp, cur_cost
                    for p in cands:
                        if not valid(p, dst):
                            continue
                        trial = dict(cur)
                        trial[dst] = p
                        c = sol_cost(trial)
                        if c < best_c - 1e-12:
                            best_p, best_c = p, c
                    if best_c < cur_cost - 1e-12:
                        cur[dst], cur_cost = best_p, best_c
                        improved = True
                if not improved:
                    break

            # Phase B: pairwise joint best-response sweeps to fixpoint.
            for _sweep in range(3):
                improved = False
                for a_i in range(len(dst_list)):
                    for b_i in range(a_i + 1, len(dst_list)):
                        da, db = dst_list[a_i], dst_list[b_i]
                        pa, pb = cur[da], cur[db]
                        best_ca, best_cb, best_c = pa, pb, cur_cost
                        for qa in cand_paths[da]:
                            if not valid(qa, da):
                                continue
                            qa_idx = {v: i for i, v in enumerate(qa)}
                            # Joint option 1: db takes a splice onto qa.
                            for qb in cand_paths[db]:
                                if not valid(qb, db):
                                    continue
                                qb_idx = {v: i for i, v in enumerate(qb)}
                                for v, ib in enumerate(qb):
                                    j = qa_idx.get(v)
                                    if j is not None:
                                        ca = qa
                                        cb = qa[: j + 1] + qb[ib + 1:]
                                        trial = dict(cur)
                                        trial[da], trial[db] = ca, cb
                                        c = sol_cost(trial)
                                        if c < best_c - 1e-12:
                                            best_ca, best_cb, best_c = ca, cb, c
                                # Joint option 2: db keeps suffix, da splices.
                                for v, ia in enumerate(qa):
                                    j = qb_idx.get(v)
                                    if j is not None:
                                        ca = qb[: j + 1] + qa[ia + 1:]
                                        trial = dict(cur)
                                        trial[da], trial[db] = ca, qb
                                        c = sol_cost(trial)
                                        if c < best_c - 1e-12:
                                            best_ca, best_cb, best_c = ca, qb, c
                        if best_c < cur_cost - 1e-12:
                            cur[da], cur[db], cur_cost = best_ca, best_cb, best_c
                            improved = True
                if not improved:
                    break

            pmap, base = cur, cur_cost
        else:
            base = float("inf")
        return pmap, base

    # Run the build+polish pipeline under both symmetrization metrics and
    # keep the cheaper plan (evaluated on the exact scored objective).
    best_map, best_cost = {}, float("inf")
    for mode in ("min", "sum"):
        try:
            pm, c = build_solution(mode)
            if c < best_cost:
                best_map, best_cost = pm, c
        except Exception:
            pass
    paths_map = best_map

    for dst, p in paths_map.items():
        record(dst, p)

    # Fallback: Dijkstra for any dst not covered by the polished tree.
    for dst in dsts:
        if dst == src or dst in paths_map:
            continue
        try:
            record(dst, nx.dijkstra_path(h, src, dst, weight="cost"))
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            pass

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


# EVOLVE-BLOCK-END

# Helper functions that won't be evolved
def create_broadcast_topology(src: str, dsts: List[str], num_partitions: int = 4):
    """Create a broadcast topology instance"""
    return BroadCastTopology(src, dsts, num_partitions)

def run_search_algorithm(src: str, dsts: List[str], G, num_partitions: int):
    """Run the search algorithm and return the topology"""
    return search_algorithm(src, dsts, G, num_partitions)

